import{_ as t,o,c as a,a2 as i}from"./chunks/framework.Dg5fKO7V.js";const g=JSON.parse('{"title":"Providers Reference","description":"","frontmatter":{},"headers":[],"relativePath":"Providers-Reference.md","filePath":"Providers-Reference.md","lastUpdated":1788563284000}'),r={name:"Providers-Reference.md"};function s(n,e,d,h,l,c){return o(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="providers-reference" tabindex="-1">Providers Reference <a class="header-anchor" href="#providers-reference" aria-label="Permalink to &quot;Providers Reference&quot;">​</a></h1><p>One page per fact about every source AniSphere can play from. <a href="./Provider-System">Provider System</a> explains the machinery. This page is the data.</p><p>Everything here is read off <code>src-tauri/src/providers/registry.rs</code>, which is the single registration point. Its order <strong>is</strong> the playback failover order.</p><hr><h2 id="the-pool-in-the-order-it-is-tried" tabindex="-1">The pool, in the order it is tried <a class="header-anchor" href="#the-pool-in-the-order-it-is-tried" aria-label="Permalink to &quot;The pool, in the order it is tried&quot;">​</a></h2><table tabindex="0"><thead><tr><th>#</th><th>Id</th><th>Name</th><th>Tracks</th><th>Handle</th><th>Code</th></tr></thead><tbody><tr><td>1</td><td><code>anikoto</code></td><td>Anikoto</td><td><code>sub</code>, <code>dub</code></td><td>AniList id</td><td><code>providers/anikoto/</code></td></tr><tr><td>2</td><td><code>anikoto2</code></td><td>Anikoto 2</td><td><code>sub</code>, <code>dub</code></td><td>site slug</td><td><code>providers/anikoto2/</code></td></tr><tr><td>3</td><td><code>anineko</code></td><td>AniNeko</td><td><code>sub</code>, <code>dub</code></td><td>site slug</td><td><code>providers/anineko/</code></td></tr><tr><td>4</td><td><code>animegg</code></td><td>AnimeGG</td><td><code>sub</code>, <code>dub</code></td><td>site slug</td><td><code>providers/animegg/</code></td></tr><tr><td>5</td><td><code>anidb</code></td><td>AniDB</td><td><code>sub</code>, <code>dub</code></td><td>site slug</td><td><code>providers/anidb/</code></td></tr><tr><td>6</td><td><code>aniworld</code></td><td>AniWorld</td><td><code>ger-dub</code>, <code>ger-sub</code></td><td>site slug</td><td><code>providers/aniworld/</code></td></tr></tbody></table><p>A provider is only asked for tracks it declares, so a German request never reaches the first five and an English one never reaches AniWorld. That is why the German pool is effectively a pool of one, and why a German title that AniWorld does not carry has nowhere else to come from.</p><p><strong>The ids are persisted.</strong> They appear in the provider-mapping table and in the user&#39;s disabled-provider setting. Renaming one orphans every mapping made against it.</p><hr><h2 id="per-provider" tabindex="-1">Per provider <a class="header-anchor" href="#per-provider" aria-label="Permalink to &quot;Per provider&quot;">​</a></h2><h3 id="anikoto-anikoto" tabindex="-1">Anikoto (<code>anikoto</code>) <a class="header-anchor" href="#anikoto-anikoto" aria-label="Permalink to &quot;Anikoto (`anikoto`)&quot;">​</a></h3><ul><li><strong>Catalogue:</strong> <code>https://anikotoapi.site</code></li><li><strong>Playback:</strong> the <a href="#megaplay">MegaPlay</a> embed</li><li><strong>Handle:</strong> the AniList id itself (<code>handle_is_anilist_id: true</code>)</li><li><strong>Connectivity map:</strong> Frankfurt (50.1, 8.7), observed host geolocated live</li></ul><p>The only provider that needs no title matching at all. MegaPlay addresses a title by the AniList id the catalogue already holds, so the handle is that id as a string and the entire class of season-matching bugs does not apply to it. That is why it is first in the pool.</p><p>It takes whatever the embed gives, which means no episode list of its own and no per-episode server choice.</p><h3 id="anikoto-2-anikoto2" tabindex="-1">Anikoto 2 (<code>anikoto2</code>) <a class="header-anchor" href="#anikoto-2-anikoto2" aria-label="Permalink to &quot;Anikoto 2 (`anikoto2`)&quot;">​</a></h3><ul><li><strong>Site:</strong> <code>https://anikoto.cz</code></li><li><strong>Playback:</strong> several servers per episode, most ending at <a href="#megaplay">MegaPlay</a></li><li><strong>Handle:</strong> site slug</li><li><strong>Connectivity map:</strong> 50.1, 14.4, observed host geolocated live</li></ul><p>The sibling that walks the site rather than the embed: a slug names a show, the show has an episode grid, and each episode lists servers. Because it reads a real episode grid it can report per-track availability honestly, which the first one cannot.</p><p>Parsing lives in <code>providers/anikoto2/parsing.rs</code> and is covered offline by <code>tests/providers/anikoto2_parsing.rs</code>.</p><h3 id="anineko-anineko" tabindex="-1">AniNeko (<code>anineko</code>) <a class="header-anchor" href="#anineko-anineko" aria-label="Permalink to &quot;AniNeko (`anineko`)&quot;">​</a></h3><ul><li><strong>Site:</strong> <code>https://anineko.to</code></li><li><strong>Handle:</strong> site slug, from <code>href=&quot;/watch/&lt;slug&gt;&quot;</code></li><li><strong>Connectivity map:</strong> Singapore (1.35, 103.8), observed host geolocated live</li></ul><p>Publishes sub and dub episode counts on its own cards, which the parser reads per track, so an absent dub is reported as absent rather than as an error. It also publishes episode titles, so it can answer <code>episode_titles_en</code>.</p><h3 id="animegg-animegg" tabindex="-1">AnimeGG (<code>animegg</code>) <a class="header-anchor" href="#animegg-animegg" aria-label="Permalink to &quot;AnimeGG (`animegg`)&quot;">​</a></h3><ul><li><strong>Site:</strong> <code>https://www.animegg.org</code></li><li><strong>Handle:</strong> site slug</li><li><strong>Connectivity map:</strong> Amsterdam (52.4, 4.9), fixed, with no live geolocation</li></ul><p>Sub and dub are separate entries on this site rather than two tracks of one entry, which is the case the pool&#39;s alternate-handle tracking exists for. Its sources are direct MP4s with a quality label rather than a playlist.</p><h3 id="anidb-anidb" tabindex="-1">AniDB (<code>anidb</code>) <a class="header-anchor" href="#anidb-anidb" aria-label="Permalink to &quot;AniDB (`anidb`)&quot;">​</a></h3><ul><li><strong>Site:</strong> <code>https://anidb.app</code>, overridable through <code>sources.json</code></li><li><strong>Handle:</strong> site slug, taken from an <code>/anime/&lt;slug&gt;-&lt;id&gt;</code> link</li><li><strong>Connectivity map:</strong> 37.8, -122.4, fixed</li></ul><p><strong>Gated on TLS fingerprint, not just headers.</strong> The request has to look like a browser all the way down to the handshake, which is why this provider&#39;s HTTP client is built differently from the others. A correct-looking request with the wrong client is refused.</p><h3 id="aniworld-aniworld" tabindex="-1">AniWorld (<code>aniworld</code>) <a class="header-anchor" href="#aniworld-aniworld" aria-label="Permalink to &quot;AniWorld (`aniworld`)&quot;">​</a></h3><ul><li><strong>Site:</strong> <code>https://aniworld.to</code>, overridable through <code>sources.json</code></li><li><strong>Tracks:</strong> <code>ger-dub</code> and <code>ger-sub</code>, the only German source in the pool</li><li><strong>Handle:</strong> site slug, and <strong>one handle covers the whole franchise</strong> (<code>seasons_under_one_handle: true</code>)</li><li><strong>Connectivity map:</strong> Frankfurt (50.1, 8.7), observed host geolocated live</li><li><strong>Extra:</strong> its own DNS-over-HTTPS resolver, <code>providers/aniworld/doh.rs</code></li></ul><p>The one provider whose handle is not per season. A franchise lives on one page and <code>solo-leveling</code> plus <code>staffel-2</code> is how season two is addressed, so the pool works out the season ordinal, strips the marker off the title, and asks for the base slug with a season hint.</p><p>The ordinal comes from three places, in order: the stored relation chain, the season suffix in the title, and a romanised sequel marker. That last one is easy to miss. <code>Yahari Ore no Seishun Love Comedy wa Machigatteiru. Zoku</code> is season two of a series whose page is called <code>my-teen-romantic-comedy-snafu</code>, and searching for the full title with <code>Zoku</code> still on it finds nothing at all. <code>Zoku</code> means two, <code>Kan</code> and <code>Final</code> mean the last one.</p><p>Knowing the season is only half of it. The site answers a search with the franchise page, and that page carries the franchise name, which is shorter than the name of the season being looked for. <code>My Teen Romantic Comedy SNAFU</code> against <code>My Teen Romantic Comedy SNAFU TOO!</code> is the whole difference between finding season two and reporting it missing, and the marker is whatever the studio called it. So for a provider that declares <code>seasons_under_one_handle</code>, a hit whose name is where one of our titles starts, with at most two words left over, is the franchise page. For the other five providers a shorter title is a different show, and the rule is unreachable.</p><p><code>MATCHING_REVISION</code> in <code>provider_pool/title_matching.rs</code> guards both. Raising it makes the pool forget every remembered miss once at the next start, which is what a fix to the matching rules needs in order to reach anyone who already ran the broken version.</p><p>When a German season is missing, this is where to look first.</p><p>Its stream links are not on the site. Each episode lists hosters, and each hoster is unwrapped separately. See <a href="#stream-hosts">Stream hosts</a> below.</p><p>Descriptions are metadata, not provider data. AniList supplies them normally and Kitsu is the fallback, so this adapter must not scrape them from the streaming site.</p><hr><h2 id="stream-hosts" tabindex="-1">Stream hosts <a class="header-anchor" href="#stream-hosts" aria-label="Permalink to &quot;Stream hosts&quot;">​</a></h2><p>A provider hands back a page. The playable URL is usually another hop from there.</p><h3 id="megaplay" tabindex="-1">MegaPlay <a class="header-anchor" href="#megaplay" aria-label="Permalink to &quot;MegaPlay&quot;">​</a></h3><p><code>providers/megaplay.rs</code>, shared by both Anikoto providers.</p><p>An embed page carries a numeric id, that id names a source document, and the source document holds the playlist. <strong>The CDN checks <code>Referer</code> and <code>Origin</code> against the site root, not against the embed page it was linked from</strong>, which is the detail that breaks a naive implementation.</p><h3 id="voe" tabindex="-1">VOE <a class="header-anchor" href="#voe" aria-label="Permalink to &quot;VOE&quot;">​</a></h3><p><code>providers/aniworld/parsing/stream_hosts.rs</code>.</p><p>VOE bounces through a landing page (<code>window.location.href = ...</code>) to a mirror, and the mirror&#39;s payload is obfuscated: a packed script, ROT13, or a JSON blob in a <code>&lt;script type=&quot;application/json&quot;&gt;</code> tag depending on the day. All three decoders are covered by fixtures in <code>tests/providers/aniworld_parsing.rs</code>.</p><h3 id="filemoon" tabindex="-1">Filemoon <a class="header-anchor" href="#filemoon" aria-label="Permalink to &quot;Filemoon&quot;">​</a></h3><p>Also in <code>stream_hosts.rs</code>. A packed script whose unpacking yields an <code>.m3u8</code>.</p><hr><h2 id="everything-a-provider-must-answer" tabindex="-1">Everything a provider must answer <a class="header-anchor" href="#everything-a-provider-must-answer" aria-label="Permalink to &quot;Everything a provider must answer&quot;">​</a></h2><p><code>src-tauri/src/providers/contract.rs</code>:</p><table tabindex="0"><thead><tr><th>Method</th><th>Answers</th></tr></thead><tbody><tr><td><code>search</code></td><td>Titles matching a query, each with an opaque handle</td></tr><tr><td><code>episodes</code></td><td>Which episodes exist for a handle and a track</td></tr><tr><td><code>episode_sources</code></td><td>Playable stream links for one episode</td></tr><tr><td><code>episode_titles_en</code></td><td>Per-episode titles, when the site publishes them</td></tr></tbody></table><p>A handle is opaque on purpose: its shape is that site&#39;s business and changes without warning, so nothing outside the provider parses one.</p><hr><h2 id="health-probes" tabindex="-1">Health probes <a class="header-anchor" href="#health-probes" aria-label="Permalink to &quot;Health probes&quot;">​</a></h2><p>Every provider declares how to prove itself end to end. The connectivity board runs these from the user&#39;s own machine, which is why it shows what is reachable for them rather than what a status page claims.</p><table tabindex="0"><thead><tr><th>Provider</th><th>Probe</th></tr></thead><tbody><tr><td>Anikoto, Anikoto 2, AniNeko, AnimeGG, AniDB</td><td>search <code>naruto</code>, <code>sub</code>, episode 1, first 4 of 5 hits</td></tr><tr><td>AniWorld</td><td>resolve slug <code>naruto</code> directly, <code>ger-sub</code>, episode 1</td></tr></tbody></table><p>AniWorld skips the search step because its slug is known and stable, and a search there costs more than it proves.</p><hr><h2 id="configuration-and-invalidation" tabindex="-1">Configuration and invalidation <a class="header-anchor" href="#configuration-and-invalidation" aria-label="Permalink to &quot;Configuration and invalidation&quot;">​</a></h2><p><code>providers/provider_config.rs</code> holds a baked default and can load a <code>sources.json</code> override from the app-data directory. Only a same-or-newer version is applied.</p><p>When the version advances, <strong>every provider mapping is dropped</strong> (<code>invalidate_stale_mappings</code>). A mapping is an agreement between one anime and one provider&#39;s handle for it, reached against the host the configuration named at the time. A new configuration voids that agreement.</p><hr><h2 id="caching-and-the-surprise-in-it" tabindex="-1">Caching, and the surprise in it <a class="header-anchor" href="#caching-and-the-surprise-in-it" aria-label="Permalink to &quot;Caching, and the surprise in it&quot;">​</a></h2><p>The pool remembers a resolved handle, and it also remembers a <strong>negative</strong> result for a shorter time. The second half is what surprises people: when a German dub has just appeared, AniSphere may not notice for up to half an hour.</p><p>Repeated failures trip a circuit breaker and take a provider out of rotation for a while. <code>PROVIDER_BLOCKED</code> short-circuits that immediately, because a refusal and an absence are different things: a provider that has no episode nine is skipped, a provider that is blocking us is removed.</p><hr><h2 id="adding-one" tabindex="-1">Adding one <a class="header-anchor" href="#adding-one" aria-label="Permalink to &quot;Adding one&quot;">​</a></h2><ol><li><code>src-tauri/src/providers/&lt;name&gt;/</code> with <code>mod.rs</code> and <code>parsing.rs</code>.</li><li>Keep <code>parsing.rs</code> pure. HTML or JSON in, structured data out, no network, so it stays testable without the site.</li><li>Implement <code>Provider</code> in <code>mod.rs</code>.</li><li>Register it in <code>providers/registry.rs</code> with its metadata and a health probe. Position in that list is failover position.</li><li>Offline tests in <code>src-tauri/src/tests/providers/</code>, against saved fixtures, plus an <code>#[ignore]</code> probe for the live path.</li></ol><p>If you find yourself editing <code>provider_pool/</code> to special-case your provider, the contract is wrong and worth fixing instead.</p><p>Read the <a href="./Legal-Disclaimer">Legal Disclaimer</a> before proposing a source.</p><hr><h2 id="things-that-will-bite-you" tabindex="-1">Things that will bite you <a class="header-anchor" href="#things-that-will-bite-you" aria-label="Permalink to &quot;Things that will bite you&quot;">​</a></h2><ul><li><strong>AniList&#39;s episode count is not permission to play.</strong> The provider&#39;s list is the truth.</li><li><strong>Sites change markup without notice.</strong> Parsing is separate and fixture-backed so a break is a failing test rather than a mystery.</li><li><strong>Some sites gate on TLS fingerprint</strong>, so the HTTP client matters as much as the request.</li><li><strong>Provider ids are persisted.</strong> Changing one orphans every stored mapping.</li><li><strong>One handle per franchise is the exception, not the rule.</strong> Only AniWorld sets it, and nearly every German season bug traces back to it.</li></ul>',73)])])}const u=t(r,[["render",s]]);export{g as __pageData,u as default};
